UPDATE t_assignment SET delete_flg = 1, updated_at = NOW() WHERE assignment_id IN
#{id}
AND delete_flg = 0

mapper.select:
	SELECT COUNT(*)
	FROM t_assignment
	WHERE delete_flg = 0
	AND emp_id = #{empId}
	AND company_id = #{companyId}
	AND contract_start_date = #{contractStartDate}
	AND (
    	contract_end_date = #{contractEndDate}
    	OR (contract_end_date IS NULL AND #{contractEndDate} IS NULL)
	)

    	AND assignment_id != #{assignmentId}

SELECT role_id FROM
m_role
WHERE role = #{role}
